INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Mercado Don Francisco','Mercado gastronómico, cultural y comercial en el antiguo Mercado Municipal de Melo. Reúne propuestas de comida, comercios y espacios de encuentro y actividades culturales en un edificio histórico renovado.','18 de Julio 637, esquina José Batlle y Ordóñez, Melo, Cerro Largo, Uruguay','Melo','+598 92 547 736','https://donfrancisco.uy/',NULL,-32.3707081,-54.1680251,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Restaurantes') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Mercado Don Francisco' AND localidad='Melo');
