INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'La Rueda','Restaurante y parrillada tradicional de Melo. Ofrece carnes a la parrilla, pastas caseras, milanesas y platos a la carta en un ambiente familiar.','General Justino Muniz 405, Melo, Cerro Largo, Uruguay','Melo','+598 4642 0142','https://www.instagram.com/laruedamelo/','Lunes cerrado; martes a sábado de 11:00 a 01:00; domingo de 11:00 a 15:30',-32.3741827,-54.1703878,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Restaurantes') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='La Rueda' AND localidad='Melo');
