INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Galpón de Piedra','Restaurante y parrilla de ambiente rústico situado en Aceguá, del lado brasileño de la frontera. Ofrece buffet, carnes y platos regionales para almorzar.','Rua 512, 355, Centro, Aceguá, Rio Grande do Sul, Brasil, 96445-000','Aceguá','+55 53 99946-0598','https://www.instagram.com/rpgalpondepiedra/','Todos los días de 11:30 a 14:00',-31.866474,-54.164682,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Restaurantes') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Galpón de Piedra' AND localidad='Aceguá');
