INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Posada San José de Lucas','Posada rural ubicada en el entorno de Tupambaé, Cerro Largo, ideal para descansar en contacto con la naturaleza. Cuenta con jardín, piscina exterior de temporada, habitaciones con aire acondicionado, conexión Wi-Fi y estacionamiento. Dispone de opciones para familias y desayuno, según las condiciones de reserva.','Camino rural sin nombre, zona de Tupambaé, Cerro Largo, Uruguay','Tupambaé','+598 91 502 405',NULL,NULL,-32.859348,-54.800461,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Alojamiento') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Posada San José de Lucas' AND localidad='Tupambaé');
