INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Hotel Juana','Hotel Juana de Ibarbourou, ubicado en Ruta 8 km 402, a las afueras de Melo. Ofrece habitaciones estándar, superiores y suites, piscina, restaurante, gimnasio, Wi-Fi y salón de eventos. Un entorno de parque pensado para descansar y disfrutar de la naturaleza.','Ruta 8, km 402, Melo, Cerro Largo, Uruguay','Melo','+598 4642 5262','https://hoteljuanamelo.com/',NULL,-32.3444395,-54.1677435,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Alojamiento') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Hotel Juana' AND localidad='Melo');
