INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Hotel Laguna Merín','Hotel situado en el balneario Lago Merín, en Calle 11, cerca de la laguna. Cuenta con habitaciones dobles, triples y suites, piscina climatizada, desayuno continental, Wi-Fi, restaurante, aire acondicionado y espacios para eventos. Una opción para descansar y disfrutar de la costa de Cerro Largo.','Calle 11, Lago Merín, Cerro Largo, Uruguay','Laguna Merín','+598 4679 8033','https://hotellagunamerin.com.uy/',NULL,-32.74491,-53.26022,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Alojamiento') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Hotel Laguna Merín' AND localidad='Laguna Merín');
