INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Casa Juana de Ibarbourou','Casa Museo de Juana de Ibarbourou, ubicada en la vivienda de Melo donde la poeta uruguaya conocida como Juana de América vivió durante su infancia y juventud. Conserva muebles, fotografías, objetos personales y recuerdos vinculados a su vida y obra literaria. Es un espacio patrimonial de gran importancia para la identidad cultural de Cerro Largo.','Treinta y Tres 317, entre Manuel Oribe y Eber da Rosa, Melo, Cerro Largo, Uruguay','Melo','+598 98 564 352','https://www.museos.gub.uy/index.php?id=745%3Acasa-museo-juana-de-ibarbourou&option=com_k2&view=item',NULL,-32.37595,-54.1677194,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Cultura') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Casa Juana de Ibarbourou' AND localidad='Melo');
