INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Posta del Chuy','Museo y Monumento Histórico Nacional ubicado a unos 13 kilómetros de Melo por Ruta 26. Construido en el siglo XIX con piedras areniscas sin argamasa, fue una posta de diligencias para viajeros entre Melo y Villa Artigas, actual Río Branco. Conserva un puente histórico sobre el arroyo Chuy del Tacuarí y elementos de la vida rural, el transporte y la cultura gaucha.','Ruta 26, aproximadamente km 13, zona rural de Melo, Cerro Largo, Uruguay','Melo','+598 4642 9147','https://www.museos.gub.uy/index.php/museos/museos-por-localidad/cerro-largo/item/20-museo-posta-del-chuy','Martes a sábado 11:00-17:00; domingo 11:00-19:00; lunes cerrado (confirmar)',-32.38238,-54.02964,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Cultura') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Posta del Chuy' AND localidad='Melo');
