INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Pulpería de Ramón Mundo','Antigua pulpería y residencia rural también conocida como Estancia Los Miradores o La Casa Quemada. Construida a mediados del siglo XIX, se destaca por sus dos torreones de vigilancia, que le daban apariencia de fortaleza. Fue propiedad de Ramón Mundo y escenario de importantes acontecimientos políticos en 1896, durante las disputas entre saravistas y municistas. Es un Monumento Histórico Nacional que conserva parte de la memoria histórica de Cerro Largo.','Estancia Los Miradores, Ruta 7 km 365, Rincón de Py, zona de Fraile Muerto, Cerro Largo, Uruguay','Fraile Muerto',NULL,'https://destinocerrolargo.uy/la-pulperia-de-ramon-mundo-y-el-inicio-de-una-guerra-politica-y-familiar/',NULL,-32.4679125,-54.4433594,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Cultura') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Pulpería de Ramón Mundo' AND localidad='Fraile Muerto');
