INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Bio Parque','Espacio recreativo y educativo de Melo dedicado a la flora y fauna autóctonas de Cerro Largo. Ofrece senderos, sectores verdes, juegos infantiles, áreas de descanso y observación de animales como carpinchos, zorros, ovejas, cabras, monos y aves. Forma parte del entorno del arroyo Conventos, próximo al Parque General Rivera. Ideal para pasear en familia y conocer la naturaleza de la región.','Ruta 26, Brigadier General Leandro Gómez, acceso oeste de Melo, Cerro Largo, Uruguay','Melo','+598 4642 9880','https://destinocerrolargo.uy/bioparque/','Todos los días de 07:00 a 20:00 (confirmar antes de visitar)',-32.36896,-54.18744,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Parques / Naturaleza') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Bio Parque' AND localidad='Melo');
