INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Playa Fraile Muerto','Balneario y camping municipal junto al arroyo Fraile Muerto, conocido también como La Playita. Cuenta con playa de agua dulce, monte y sombra natural, parrilleros, espacios para picnic y acampe, así como cabañas municipales. El área recreativa permite disfrutar del paisaje del arroyo y de actividades al aire libre. Se ha informado de una rampa de acceso a la playa para personas con movilidad reducida; consultar condiciones del agua y servicios antes de ingresar.','Balneario municipal de Fraile Muerto, acceso por Ruta 7, junto al arroyo Fraile Muerto, Cerro Largo, Uruguay','Fraile Muerto',NULL,'https://www.gub.uy/ministerio-turismo/comunicacion/noticias/se-realizo-mision-tecnica-del-mintur-departamento-cerro-largo-identificando',NULL,-32.5200625,-54.5275625,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Parques / Naturaleza') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Playa Fraile Muerto' AND localidad='Fraile Muerto');
