INSERT INTO ubicacion(nombre,descripcion,direccion,localidad,telefono,sitio_web,horario,latitud,longitud,estado,id_categoria) SELECT 'Parque Rivera','Parque General Fructuoso Rivera, uno de los principales espacios verdes de Melo, ubicado cerca del arroyo Conventos y del Bio Parque. Dispone de senderos para caminar, áreas de descanso, juegos infantiles, mesas para picnic, parrilleros y sectores deportivos. El entorno conserva referencias históricas vinculadas al general Fructuoso Rivera y es un tradicional paseo familiar de Cerro Largo.','Ruta 26, acceso oeste de Melo, junto al arroyo Conventos, Cerro Largo, Uruguay','Melo',NULL,'https://www.gub.uy/intendencia-cerro-largo/comunicacion/noticias/intendencia-inaugura-recuperacion-espacio-parque-rivera','Espacio abierto todos los días; ficha pública indica acceso las 24 horas',-32.37057,-54.18943,'PUBLICADO', (SELECT id FROM categoria WHERE nombre='Parques / Naturaleza') WHERE NOT EXISTS(SELECT 1 FROM ubicacion WHERE nombre='Parque Rivera' AND localidad='Melo');
